"""Consumer-only native round certificate data; no nonmaterialized graph claims."""
import hashlib,json,os
from pathlib import Path
from validate_records import validate_node
S=Path(__file__).resolve().parent;R=S.parents[1];O=R/'outputs/mac-poseidon-late03';P=S/'project/ShielddSecurity';D=O/'rounds01.json'
h=lambda b:hashlib.sha256(b).hexdigest();raw=D.read_bytes();assert h(raw)=='22abb7056663e338578dfe70c1a695fb04782ae0e7df737fab86605fffa97b62';d=json.loads(raw)
assert d['runtime_sha']=='844389ee069e1fb2e576708842d0b389b4d9a44a'
assert h((P/'TransferPoseidonParameters02.lean').read_bytes())=='2faba8654740679c2315c0adfc65e7e884ef2bb4bc50ccb6cb13f0769743428f'
scope=d['selected_rounds'][0];assert scope['round']==61 and scope['full'] and len(scope['nodes'])==96
ns='ShielddSecurity.TransferPoseidonLate03';nodes={n['source_node']:n for n in scope['nodes']};cuts={n['source_node']:n for n in scope['external_ports']};constants={c['source_constant']:c['integer'] for c in scope['constants']};rows={r['capture_index']:r for r in d['indexed_original_rows']};pool={};records=[]
def lc(terms):
 key=tuple(map(tuple,terms))
 if key not in pool:pool[key]='lc'+str(len(pool))
 return pool[key]
def refTerms(ref):
 kind,index=ref
 if kind==2:return nodes[index]['expression']['terms'] if index in nodes else cuts[index]['expression']['terms']
 if kind==0:return [[0,constants[index]]] if constants[index] else []
 raise AssertionError(ref)
steps=[]
for n in scope['nodes']:
 validate_node(n);c=n['certificate'];ctor=c['constructor']
 if ctor in ['foldedLeft','foldedRight']:
  port=n['left'] if ctor=='foldedLeft' else n['right'];assert port[0]==0 and c['coefficient']==constants[port[1]]
 if ctor not in ['square','product']:continue
 ts=n['expression']['terms'];assert len(ts)==1 and ts[0][1]==1
 x=lc(refTerms(n['left']));y=lc(refTerms(n['right']));out=ts[0][0]
 if ctor=='square':assert n['left']==n['right'];steps.append(f'.square {x} [] {out}')
 else:
  assert len(c['auxiliary'])==1 and c['auxiliary'][0][1]==1 and c['auxiliary'][0][0]!=out
  steps.append(f'.product {x} {y} [] {out} {c["auxiliary"][0][0]}')
assert len(steps)==18
phase={name:[lc(refTerms(ref)) for ref in scope['phase_ports'][key]] for name,key in [('before','before'),('shifted','after_ark'),('transformed','after_sbox'),('after','after_mds')]}
assert all(len(refTerms(ref))==64 for ref in scope['phase_ports']['before']+scope['phase_ports']['after_ark'])
rowindices=scope['rows_with_actual_copy_link'];assert rowindices==list(range(638,662))+[200769];rowmap={v:i for i,v in enumerate(rowindices)}
hints=[]
for col,ref in enumerate(scope['phase_ports']['after_sbox']):
 prod=nodes[ref[1]];c=prod['certificate'];assert c['constructor']=='product' and prod['right']==scope['phase_ports']['after_ark'][col]
 fourth=nodes[prod['left'][1]];square=nodes[fourth['left'][1]]
 assert fourth['certificate']['constructor']=='square' and fourth['left']==fourth['right']
 assert square['certificate']['constructor']=='square' and square['left']==square['right']==scope['phase_ports']['after_ark'][col]
 hints.append('⟨'+', '.join([lc(square['expression']['terms']),lc(fourth['expression']['terms']),lc(c['auxiliary'])]+list(map(str,[rowmap[square['certificate']['rows'][0]],rowmap[fourth['certificate']['rows'][0]],rowmap[c['rows'][0]],rowmap[c['rows'][1]]])))+'⟩')
rowdefs=[f'def row{i} : Row := ⟨{lc(rows[r]["a"])},{lc(rows[r]["b"])}⟩' for i,r in enumerate(rowindices)]
lines=['-- GENERATED by generate_direct.py; edit generator.','import ShielddSecurity.PoseidonIndexedRound01','import ShielddSecurity.CompilerOrder','import ShielddSecurity.CompilerPriorFrame01','import ShielddSecurity.TransferPoseidonParameters02','set_option maxHeartbeats 900000','set_option maxRecDepth 8192',f'namespace {ns}','open Compiler CompilerIndexed01 CompilerCompletion Poseidon PoseidonIndexedRound01',f'def p : Nat := {d["modulus"]}',f'def copy : Nat := {d["constant_copy"]}','def parameters : Parameters Int 6 := TransferPoseidonParameters02.parameters']
lines += [f'def {name} : Linear := ['+', '.join(f'({col},{coef})' for col,coef in terms)+']' for terms,name in pool.items()]
for name,refs in phase.items():lines += [f'def {name} (column : Fin 6) : Linear := match column.val with']+[f'  | {i} => {ref}' for i,ref in enumerate(refs)]+['  | _ => []']
lines += rowdefs+['def originalRows : Array Row := Array.mk ['+', '.join(f'row{i}' for i in range(25))+']','def captureIndices : Array Nat := Array.mk ['+', '.join(map(str,rowindices))+']','def fifthHints (column : Fin 6) : FifthHint := match column.val with']+[f'  | {i} => {v}' for i,v in enumerate(hints)]+['  | _ => ⟨[],[],[],0,0,0,0⟩','def materializedSteps : List Step := [\n  '+',\n  '.join(steps)+']','def copyStep : Step := .equal [(0,1)] [(0,1)]','def steps : List Step := materializedSteps++[copyStep]','def emittedRows : Array Row := (emitted steps).toArray','def rowMapping : Array Nat := (List.range 25).toArray','def cutTerms (state : State Linear 6) (input : Nat) : Linear := if bound : input<6 then state ⟨input,bound⟩ else []','def productionCheck (candidateRows : Array Row) (candidateParameters : Parameters Int 6)',
 '    (candidateBefore candidateAfter : State Linear 6) (candidateHints : Fin 6 → FifthHint) (mapping : Array Nat) : Bool :=',
 '  checkRowAt p candidateRows 24 ⟨[(0,1),(copy,-1)],[]⟩ &&',
 '  checkRound p copy candidateRows candidateParameters 61 candidateBefore shifted transformed candidateAfter candidateHints &&',
 '  checkOriginalCoverage p copy candidateRows emittedRows mapping &&',
 '  CompilerPriorFrame01.checkSupport 6 (cutTerms candidateBefore) steps',f'end {ns}']
def save(module,lines):
 b=('\n'.join(lines)+'\n').encode();p=P/(module+'.lean')
 if p.exists() and p.read_bytes()!=b:
  hist=O/'source-history';hist.mkdir(exist_ok=True);old=p.read_bytes();(hist/(module+'-'+h(old)+'.lean')).write_bytes(old)
 tmp=p.with_suffix('.tmp');tmp.write_bytes(b);os.replace(tmp,p);records.append(dict(module=module,sha256=h(b),bytes=len(b)))
save('TransferPoseidonLate03Data01',lines)
header=lambda module:['-- GENERATED by generate_direct.py; edit generator.','import ShielddSecurity.TransferPoseidonLate03Data01','set_option maxHeartbeats 900000','set_option maxRecDepth 8192','namespace ShielddSecurity.'+module,'open Compiler CompilerIndexed01 CompilerCompletion Poseidon PoseidonIndexedRound01 TransferPoseidonLate03']
def theorem(lines,name,body,module):
 lines.extend([f'theorem {name} : '+body,'set_option pp.all true in',f'#check @ShielddSecurity.{module}.{name}',f'#print axioms ShielddSecurity.{module}.{name}'])
module='TransferPoseidonLate03ConsumerChecks01';lines=header(module)
for i in range(6):theorem(lines,f'column{i}_checked',f'checkColumn p copy originalRows parameters 61 before shifted transformed fifthHints ⟨{i},by decide⟩=true := by decide +kernel',module)
for i in range(6):theorem(lines,f'mix{i}_checked',f'canonical p (after ⟨{i},by decide⟩)=canonical p (mixLinear parameters.mds transformed ⟨{i},by decide⟩) := by decide +kernel',module)
lines+=['end ShielddSecurity.'+module];save(module,lines)
module='TransferPoseidonLate03CoverageChecks01';lines=header(module)
for i in range(25):theorem(lines,f'row{i}_checked',f'checkOriginalAt p copy originalRows emittedRows rowMapping {i}=true := by decide +kernel',module)
lines+=['end ShielddSecurity.'+module];save(module,lines)
module='TransferPoseidonLate03ProgramChecks01';lines=header(module)
for name,body in [('actual_copy_checked','checkRowAt p originalRows 24 ⟨[(0,1),(copy,-1)],[]⟩=true'),('ordered_checked','CompilerOrder.checkOrder [0,copy] [] steps=true'),('writes_checked','(PoseidonCompletion.writes steps).all (fun column => decide (23376≤column ∧ column≤23399))=true'),('cut_support_checked','CompilerPriorFrame01.checkSupport 6 (cutTerms before) steps=true'),('raw_support_checked','originalRows.toList.all (fun row => (row.a++row.b).all (fun term => decide (term.1≤23399 ∨ term.1=copy)))=true'),('rows_shape','originalRows.size=25 ∧ materializedSteps.length=18 ∧ steps.length=19 ∧ captureIndices.toList=List.range\' 638 24++[200769]')]:theorem(lines,name,body+' := by decide +kernel',module)
lines+=['end ShielddSecurity.'+module];save(module,lines)
assert D.read_bytes()==raw
idx=1
while (O/f'direct-generation{idx:02d}.json').exists():idx+=1
receipt=dict(generator_sha256=h(Path(__file__).read_bytes()),validator_sha256=h((S/'validate_records.py').read_bytes()),descriptor_sha256=h(raw),sources=records,pool_bodies=len(pool),pool_terms=sum(map(len,pool)),consumer_only=True,typed_nonmaterialized_graph_claim=False,full_transfer='OPEN')
(O/f'direct-generation{idx:02d}.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt))
